mapper.update:
UPDATE orders
SET status = #{status}
WHERE id = #{id}

UPDATE orders
SET order_group_id = #{groupId}
WHERE id = #{id}

mapper.select:
SELECT o.id, o.user_id, o.stall_id, o.subtotal, o.discount_total, o.total_amount, o.payment_method, o.status, o.created_at, u.username AS username FROM orders o JOIN users u ON u.id = o.user_id WHERE o.stall_id = #{stallId}
AND o.status = #{status}
ORDER BY o.id DESC

SELECT o.id, o.user_id, o.stall_id, o.order_group_id, o.subtotal, o.discount_total, o.total_amount, o.payment_method, o.status, o.created_at, s.name AS stall_name FROM orders o LEFT JOIN stalls s ON s.id = o.stall_id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.id DESC

SELECT COUNT(*)
FROM orders o
JOIN order_items oi ON oi.order_id = o.id
WHERE o.user_id = #{userId}
  AND oi.menu_item_id = #{menuItemId}
  AND o.status IN ('READY', 'PICKED_UP')
